const HADITHS=[{text:"إنما الأعمال بالنيات وإنما لكل امرئ ما نوى، فمن كانت هجرته إلى الله ورسوله فهجرته إلى الله ورسوله، ومن كانت هجرته لدنيا يصيبها أو امرأة ينكحها فهجرته إلى ما هاجر إليه",narrator:"عمر بن الخطاب",source:"صحيح البخاري ومسلم",grade:"صحيح",category:"الإيمان"},{text:"من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت، ومن كان يؤمن بالله واليوم الآخر فليكرم جاره، ومن كان يؤمن بالالله واليوم الآخر فليكرم ضيفه",narrator:"أبو هريرة",source:"صحيح البخاري ومسلم",grade:"صحيح",category:"الأخلاق"},{text:"لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه",narrator:"أنس بن مالك",source:"صحيح البخاري ومسلم",grade:"صحيح",category:"الإيمان"},{text:"المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه",narrator:"عبد الله بن عمرو",source:"صحيح البخاري",grade:"صحيح",category:"الأخلاق"},{text:"من سلك طريقاً يلتمس فيه علماً سهل الله له به طريقاً إلى الجنة",narrator:"أبو هريرة",source:"صحيح مسلم",grade:"صحيح",category:"العلم"},{text:"صلّوا كما رأيتموني أُصلّي",narrator:"مالك بن الحويرث",source:"صحيح البخاري",grade:"صحيح",category:"الصلاة"},{text:"من صلى العشاء في جماعة فكأنما قام نصف الليل ومن صلى الفجر في جماعة فكأنما صلى الليل كله",narrator:"عثمان بن عفان",source:"صحيح مسلم",grade:"صحيح",category:"الصلاة"},{text:"الطهور شطر الإيمان والحمد لله تملأ الميزان وسبحان الله والحمد لله تملآن ما بين السماوات والأرض",narrator:"أبو مالك الأشعري",source:"صحيح مسلم",grade:"صحيح",category:"الذكر والدعاء"},{text:"من صام رمضان إيماناً واحتساباً غفر له ما تقدم من ذنبه",narrator:"أبو هريرة",source:"صحيح البخاري ومسلم",grade:"صحيح",category:"الصيام"},{text:"لا تتحرجوا في الدعاء فإنه لا يهلك مع الدعاء أحد",narrator:"أبو هريرة",source:"سنن ابن ماجه",grade:"حسن",category:"الذكر والدعاء"},{text:"رضا الرب في رضا الوالد وسخط الرب في سخط الوالد",narrator:"عبد الله بن عمرو",source:"الترمذي",grade:"حسن",category:"بر الوالدين"},{text:"عجباً لأمر المؤمن إن أمره كله خير، إن أصابته سراء شكر فكان خيراً له وإن أصابته ضراء صبر فكان خيراً له",narrator:"صهيب الرومي",source:"صحيح مسلم",grade:"صحيح",category:"الصبر"},{text:"الراحمون يرحمهم الرحمن، ارحموا من في الأرض يرحمكم من في السماء",narrator:"عبد الله بن عمرو",source:"أبو داود والترمذي",grade:"صحيح",category:"الرحمة"},{text:"خيركم من تعلم القرآن وعلمه",narrator:"عثمان بن عفان",source:"صحيح البخاري",grade:"صحيح",category:"العلم"},{text:"اتق الله حيثما كنت وأتبع السيئة الحسنة تمحها وخالق الناس بخلق حسن",narrator:"معاذ بن جبل",source:"سنن الترمذي",grade:"حسن",category:"الأخلاق"},{text:"إن الله لا ينظر إلى صوركم وأموالكم ولكن ينظر إلى قلوبكم وأعمالكم",narrator:"أبو هريرة",source:"صحيح مسلم",grade:"صحيح",category:"الإيمان"}];
