const PROPHET_STORIES=[{name:"آدم عليه السلام",icon:"fas fa-leaf",intro:"أبو البشر وأول الأنبياء، خلقه الله بيده ونفخ فيه من روحه.",events:"بدأت قصة آدم حين أمر الله الملائكة بالسجود له فسجدوا إلا إبليس. ثم أسكنه الله الجنة، وزوجته حواء، ونهاه عن شجرة واحدة. ولكن وسوس له الشيطان فأكلا منها، فتاب الله عليهما وهداهما.",verses:"﴿وَقُلْنَا يَا آدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ﴾",lessons:"1. خطورة الحسد والعناد. 2. باب التوبة مفتوح للجميع. 3. الشيطان عدو مبين للإنسان."},{name:"نوح عليه السلام",icon:"fas fa-water",intro:"شيخ المرسلين، دعا قومه 950 سنة.",events:"دعا نوح قومه إلى عبادة الله وحده ليلاً ونهاراً، ولكنهم كذبوه وأعرضوا. فأمره الله ببناء السفينة، وحمل فيها من كل زوجين اثنين، ثم جاء الطوفان فأغرق الكافرين ونجى المؤمنين.",verses:"﴿وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُمْ مُغْرَقُونَ﴾",lessons:"1. الصبر في الدعوة. 2. نجاة المؤمنين وهلاك المكذبين. 3. أهمية الإيمان والعمل الصالح."},{name:"إبراهيم عليه السلام",icon:"fas fa-fire",intro:"خليل الرحمن، أبو الأنبياء.",events:"حطم إبراهيم أصنام قومه، فألقوه في النار، ولكن الله جعلها برداً وسلاماً عليه. ثم ابتلاه الله بذبح ابنه إسماعيل، فاستسلم لأمر الله، ففداه الله بكبش عظيم.",verses:"﴿يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَى إِبْرَاهِيمَ﴾",lessons:"1. التضحية في سبيل الله. 2. قوة الإيمان تتحدى العقبات. 3. صدق اليقين يصنع المعجزات."},{name:"موسى عليه السلام",icon:"fas fa-staff",intro:"كليم الله، نجا بني إسرائيل من فرعون.",events:"أرسله الله إلى فرعون، فدعاه إلى التوحيد، فاستكبر فرعون. فأرسل الله الآيات، ثم أمر موسى أن يضرب البحر بعصاه، فانفلق ونجى بنو إسرائيل وغرق فرعون.",verses:"﴿فَأَوْحَيْنَا إِلَى مُوسَى أَنِ اضْرِبْ بِعَصَاكَ الْبَحْرَ فَانْفَلَقَ فَكَانَ كُلَّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ﴾",lessons:"1. التوحيد ينتصر على الطغيان. 2. معية الله للمؤمنين. 3. الصبر على أذى الظالمين."},{name:"عيسى عليه السلام",icon:"fas fa-dove",intro:"روح الله وكلمته، ولد من غير أب.",events:"ولد عيسى من مريم العذراء بمعجزة، تكلم في المهد، وأحيا الموتى، وأبرأ الأعمى بإذن الله. ولم يمت بل رفعه الله إليه، وسينزل في آخر الزمان.",verses:"﴿إِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِنْهُ اسْمُهُ الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ﴾",lessons:"1. قدرة الله تتجاوز الأسباب. 2. التواضع وعبادة الله. 3. الإيمان باليوم الآخر."},{name:"محمد ﷺ",icon:"fas fa-star-and-crescent",intro:"خاتم الأنبياء والمرسلين، رحمة للعالمين.",events:"ولد في مكة يتيماً، وبعثه الله في الأربعين. تحمل الأذى في الدعوة، وهاجر إلى المدينة، وأسس دولة الإسلام، وفتح مكة، وانتشر دين الله في الأرض.",verses:"﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ﴾",lessons:"1. الرحمة في الدعوة. 2. الصبر والثبات. 3. اكتمال الدين برسالته."}];

