const JUDGMENT_DATA = [
  { title: "1- علامات الساعة", icon: "fas fa-clock", content: "علامات الساعة هي الأدلة التي تدل على اقتراب يوم القيامة، وتنقسم إلى صغرى وكبرى. من العلامات الصغرى: بعثة النبي ﷺ، وانتشار الفتن، وتطاول الناس في البنيان، وكثرة الزلازل. ومن العلامات الكبرى: خروج المهدي، ونزول عيسى عليه السلام، وخروج الدجال، وطلوع الشمس من مغربها، وخروج الدابة من الأرض. قال ﷺ: 'بعثت أنا والساعة كهاتين'." },
  { title: "2- النفخ في الصور", icon: "fas fa-trumpet", content: "الصور قرن ينفخ فيه إسرافيل عليه السلام بأمر الله. النفخة الأولى (نفخة الصعق) يموت بها جميع من في السماوات والأرض إلا من شاء الله، قال تعالى: ﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ﴾. ثم يأمر الله إسرافيل بالنفخة الثانية (نفخة البعث) فيقوم الناس من قبورهم." },
  { title: "3- البعث بعد الموت", icon: "fas fa-seedling", content: "البعث هو إحياء الله للموتى يوم القيامة، وهو إثبات لقدرة الله وعظمته. قال تعالى: ﴿وَأَنَّ السَّاعَةَ آتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ اللَّهَ يَبْعَثُ مَن فِي الْقُبُورِ﴾. يبعث الله الناس من قبورهم حفاة عراة غرلاً (غير مختونين)، كما بدأهم الله أول مرة يعيدهم." },
  { title: "4- خروج الناس من القبور", icon: "fas fa-door-open", content: "عند النفخة الثانية، تتشقق القبور ويخرج منها الناس مسرعين إلى ربهم، قال تعالى: ﴿يَوْمَ يَخْرُجُونَ مِنَ الْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ﴾. يخرجون مبهورين من هول المطلع، يقول الكافر: ﴿يَا وَيْلَتَنَا مَن بَعَثَنَا مِن مَّرْقَدِنَا﴾." },
  { title: "5- أرض المحشر", icon: "fas fa-globe", content: "أرض المحشر هي الأرض التي يجمع الله فيها الخلائق يوم القيامة، وهي أرض بيضاء مستوية ليس فيها معلم لأحد. قال النبي ﷺ: 'يُحشر الناس يوم القيامة على أرض بيضاء عفراء كقرص النقى ليس فيها معلم لأحد'." },
  { title: "6- اجتماع الخلائق للحساب", icon: "fas fa-users", content: "يجمع الله الأولين والآخرين في صعيد واحد، يجتمعون في موقف عظيم مهيب. قال تعالى: ﴿يَوْمَ نَطْوِي السَّمَاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُّعِيدُهُ﴾. يدنو الشمس من رؤوسهم حتى يبلغ العرق منهم أشدهم، ويقول بعضهم لبعض: ألستم تريدون من يقوم لكم فيحكم بينكم؟ فيأتون آدم ونوحاً وإبراهيم وموسى وعيسى حتى ينتهوا إلى النبي محمد ﷺ." },
  { title: "7- عرض الأعمال", icon: "fas fa-book-open", content: "يعرض الله على كل عبد عمله يوم القيامة، صغيره وكبيره. قال تعالى: ﴿وَوَجَدُوا مَا عَمِلُوا حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا﴾. المؤمن يرى عمله فيفرح ويزداد سروراً، والكافر يرى عمله فيتحسر ويتمنى لو لم يعمل سوءاً." },
  { title: "8- الحساب", icon: "fas fa-calculator", content: "الحساب هو أن الله يوقف عبده بين يديه فيسأله عن جميع أعماله. قال النبي ﷺ: 'لا تزول قدما عبد يوم القيامة حتى يُسأل عن أربع: عن عمره فيم أفناه، وعن شبابه فيم أبلاه، وعن ماله من أين اكتسبه وفيم أنفقه، وعن علمه ماذا عمل فيه'. ومن يُحاسب حساباً يسيراً يناقش في كتابه، ومن يُحاسب حساباً عسيراً يُسأل عن كل شيء." },
  { title: "9- الميزان", icon: "fas fa-balance-scale", content: "الميزان هو ما يضعه الله يوم القيامة لوزن أعمال العباد. قال تعالى: ﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا﴾. توزن فيه صحائف الأعمال، فمن ثقلت موازينه فله عيشة راضية، ومن خفت موازينه فأمه هاوية." },
  { title: "10- الصراط", icon: "fas fa-route", content: "الصراط هو جسر منصوب على متن جهنم، أدق من الشعرة وأحد من السيف. يمر عليه الناس بحسب أعمالهم، فمنهم من يمر كالبرق، ومنهم من يمر كالريح، ومنهم من يمر كالفرس، ومنهم من يمر كالراكب، ومنهم من يخطفه كلاليب النار. قال النبي ﷺ: 'يمر الناس على الصراط فمنهم من يمر كلمح البصر، ومنهم من يمر كالريح، ومنهم من يمر كالطير، ومنهم من يمر كالفرس الجواد'." },
  { title: "11- الشفاعة", icon: "fas fa-hands-praying", content: "الشفاعة هي إذن الله لمن يختاره من عباده أن يشفع لمن يرتضي. أعظم الشفاعات هي الشفاعة العظمى للنبي محمد ﷺ في فصل القضاء، وهي المقام المحمود. ومن الشفاعات: شفاعته ﷺ لعمه أبي طالب بتخفيف العذاب، وشفاعته لأهل الجنة بدخولها، وشفاعة الشهداء والعلماء والقرآن. قال تعالى: ﴿مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ﴾." },
  { title: "12- دخول الجنة", icon: "fas fa-door-open", content: "الجنة هي دار النعيم التي أعدها الله للمؤمنين جزاءً لأعمالهم الصالحة. قال تعالى: ﴿وَعَدَ اللَّهُ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا﴾. يدخلها المؤمنون بعد أن يجوزوا الصراط، فينادى لهم: ادخلوها بسلام آمنين. فيها ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر." },
  { title: "13- دخول النار", icon: "fas fa-fire", content: "النار هي دار العذاب التي أعدها الله للكافرين والعصاة. قال تعالى: ﴿وَاتَّقُوا النَّارَ الَّتِي أُعِدَّتْ لِلْكَافِرِينَ﴾. يدخلها الكفار خلوداً أبدياً لا يخرجون منها أبداً. أما العصاة من الموحدين فيعذبون فيها بقدر ذنوبهم، ثم يخرجهم الله منها برحمته وشفاعة الشفعاء، ويدخلهم الجنة." }
];

